/** One positional parameter of an **E**lement **P**laceholder (mirrors the form package's EPParamSpec). */
interface CodbiEPParamSpec {
  /** The 1-based position of this parameter. */
  index: number;
  /** An optional human readable label. */
  name?: string;
  /** The datatype hint (defaults to "any"). */
  type: string;
  /** Whether the parameter may be omitted. */
  optional?: boolean;
  /** Whether further trailing parameters may follow. */
  variadic?: boolean;
  /** A short human readable description (a plain string or a per-language map). */
  description?: string | { [lang: string]: string };
}
/** A resolved **E**lement **P**laceholder signature (mirrors the form package's EPSignature). */
interface CodbiEPSignature {
  /** The ordered parameter specifications. */
  params: Array<CodbiEPParamSpec>;
  /** The datatype hint for the EP's result. */
  returnType?: string;
  /** Where the signature originated from. */
  source: string;
}
/**
 * Augments the {@link window } in order to provide globally available
 * CodBi-Related information. */
interface Window {
  /** Stores the currently used overall language. */
  XFC_METADATA: {
    currentLanguage: string;
  };
  /** Stores data related to the CodBi. */
  CodbiPluginData: {
    /** Stores the Standard-Configurations available. */
    detStandards: {
      [key: string]: {
        /** Stores the either the URL to or the actual HTML of the documentation. */
        Description: string;
        /** Stores a boolean indicating whether this configuration is selected as to be used in the form designer. */
        Active: boolean;
        /**
         * The CSS-Classes that this configuration provides, keyed by class name. Under the optimised
         * shape each class's entry holds BOTH its human-readable description AND its FORMCYCLE
         * widget list (`formelementtypes`), so the class name is not repeated in a separate map:
         *
         * `classes[cssClass] = { description, formelementtypes?: string[] }`
         *
         * `formelementtypes` absent/empty ⇒ that class applies to **any** element (fail-open). The
         * legacy/manager form (`classes[cssClass]` = a plain description string) also remains valid. */
        classes: { [key: string]: { description?: string; formelementtypes?: Array<string> } | string };
        /** Stores the global variables that this configuration provides. */
        globals: { [key: string]: string };
        /**
         * Maps each CSS-Class (that is a `loadConfig` target) to the comma-separated
         * list of **CodBi-Functionalities** (`FUNC`) applied to elements carrying that class.
         * Absent for classes that are not configuration targets (e.g. plain sub-selectors). */
        funcs?: { [key: string]: string };
        /**
         * The FORMCYCLE widget-class marker of a **holistic** standard configuration. A regular
         * (non-holistic) config `.json` — as regenerated by
         * `scripts/generate-supported-formelementtypes-for-configurations.mjs` — carries **no** value
         * here: each regular CSS-Class's widget list lives in its own `classes[cssClass].formelementtypes`.
         *
         * Only the literal array `["Holistic"]` (case-insensitive) marks a **holistic** configuration
         * that is hidden from the per-element standard-configuration listings of the form-element
         * CodBi panel. A bare `string`/`string[]` is the legacy/synthetic file-level form (e.g. the
         * local API-doc / manager channel). An absent property means the config is regular and each
         * class is matched by its own widget list (fail-open when a class has none). */
        supportedFormelementtypes?: Array<string> | string;
      };
    };
    /** Stores the available **CodBi-Functionalities**. */
    detFunctionalities: {
      [key: string]: {
        /** Stores the either the URL to or the actual HTML of the documentation. */
        Description: string;
        /**
         * A very short (one-sentence) description of the **CodBi-Functionality**, shown as the tooltip
         * of the parameter functionality group header in the config panel. A plain string or a
         * per-language map (e.g. `{ en, de, it }`), resolved via `localizedFunctionalitySummary`. */
        Summary?: string | { [lang: string]: string };
        /** Stores the parameter that this **CodBi-Functionality** provides. */
        Parameter: { [key: string]: string };
        /**
         * The per-parameter TYPE metadata (boolean/string/integer/number/enum), keyed by parameter name.
         * Published by the build-time generator (`@ParameterTypes`) or the local API-doc manager; the
         * designer renders a type-appropriate editor from it (checkbox, number box, dropdown, text). */
        parameters?: {
          [name: string]: {
            type?: "string" | "integer" | "number" | "boolean" | "enum";
            options?: string[];
            default?: string;
            description?: string;
          };
        };
        /**
         * LEGACY alias of {@link supportedFormelementtypes}: the FORMCYCLE widget class names this
         * functionality is intended for (e.g. `XFieldSet`). Empty/absent means "any element"
         * (fail-open). Still read as a fallback, but the local API-doc manager now WRITES the
         * canonical {@link supportedFormelementtypes} so its selection overrides the build-time
         * applicability in the designer. */
        formElements?: Array<string>;
        /** The `@SupportedFormelementtype` spec (widget classes + per-type property constraints). */
        supportedFormelementtypes?:
          | string
          | Array<string>
          | { [type: string]: { [property: string]: string | Array<string> } | undefined };
        /** The rich requirements (widget classes + per-type property constraints); absent = any. */
        requirements?: Array<{ type: string; properties?: { [property: string]: Array<string> } }>;
      };
    };
    /**
     * Stores the **form-element-type** metadata of the CodBi functionalities, keyed by (lowercase)
     * functionality id. Published by the build-time generator or the local API-doc manager; the
     * runtime merges it with anything provided via `describeFunctionality`. */
    funcMeta?: {
      [key: string]: {
        /** The widget class names the functionality applies to (empty = any). */
        formElements: Array<string>;
        /** The rich requirements (widget classes + per-type property constraints); absent = any. */
        requirements?: Array<{ type: string; properties?: { [property: string]: Array<string> } }>;
        /** The tier that produced this entry. */
        source?: string;
      };
    };
    /** Stores the available Element-Placeholder. */
    detElementplaceholder: {
      [key: string]: {
        /** Stores the either the URL to or the actual HTML of the documentation. */
        Description: string;
        /** Stores the parameter that this **Element-Placeholder** provides. */
        Parameter?: { [key: string]: string };
        /** Stores the typed signature resolved by the build-time generator (Tier A) or the manager (Tier B). */
        Signature?: CodbiEPSignature;
        /** A very short (one-sentence) description of the **E**lement **P**laceholder (string or per-language map). */
        Summary?: string | { [lang: string]: string };
        /** Whether this entry is a **locally** defined EP (registered via the Local API-doc manager). */
        local?: boolean;
      };
    };
    /** Stores the resolved **E**lement **P**laceholder signatures keyed by (lowercase) EP id. */
    epSignatures?: { [key: string]: CodbiEPSignature };
    /** Stores the URLs pointing to the root of localized API-Documentations. */
    docsAPI: {
      [key: string]: string;
    };
    /** Stores a CSV stating the actual file's names where the code for **Standard-Configurations** resides. */
    fileListing: string;
    /** Stores a CSV stating the actual file's names where the code for **Element-Placeholder** resides. */
    fslElementplaceholder: string;
    /** Stores a CSV stating the actual file's names where the code for **CodBi-Functionalities** resides. */
    fslFunctionalities: string;
    /**
     * Re-renders the per-element CodBi config panel of the currently selected element in place (its
     * functionality/standard-configuration listings are computed from `detFunctionalities` at render
     * time). Registered by the per-element config editor; called by the local API-doc manager after a
     * successful sync so a changed `supportedFormelementtypes` shows up without a designer reload.
     * Absent until the designer has registered the per-element CodBi properties. */
    refreshElementConfig?: () => void;
    /**
     * Opens the documentation of one **CodBi-Functionality** or **standard configuration** in the
     * shared API-Doc viewer — the very viewer the attribute-config (`ALT+F`) and CSS-config (`.`)
     * flows use. Published by the local API-doc interface and called by the per-element CodBi config
     * panel's functionality/standard-configuration listings on right-click. Absent until the local
     * API-doc interface has been enabled.
     *
     * @param kind   The registry to read the description from.
     * @param id     The functionality id (matched case-insensitively) or the standard-configuration id.
     * @param anchor The listing row the viewer is anchored/positioned next to.
     */
    showCodbiDoc?: (kind: "functionality" | "standard", id: string, anchor?: HTMLElement | null) => void;
    /**
     * Notifies the shared API-Doc viewer that the pointer left the listing row whose documentation it
     * currently shows (see {@link showCodbiDoc}). The viewer stays open when the pointer reaches it in
     * time, otherwise it dismisses after a short grace period.
     */
    codbiDocAnchorLeft?: () => void;
    /**
     * The plugin's BUILD token — the very version the designer's own resources are served with
     * (`designer.js?v=<buildVersion>`): a per-build timestamp for development builds, the release
     * version otherwise. Used to cache-bust the hand-injected Angular manager bundle
     * (`cb-manager.js`), whose URL carries no version of its own — see `codbiManagerCacheSuffix()`.
     * Absent with an older plugin, in which case the manager URLs stay unversioned. */
    buildVersion?: string;
    /** Re-Populates the **Standard-Configuration** listing displayed in the form designer's form properties tab.*/
    populateStandards: () => void;
    /**
     * Programmatically sets the active standard configurations CSV, updates the MultiSelect
     * checkboxes, and fires the **set-property** callback so the form designer persists the change.
     * Only available after the MultiSelect editor has been instantiated (form properties panel opened).
     *
     * @param csv Comma-separated list of active standard configuration names.
     */
    setStandardsValue?: (csv: string) => void;
    /**
     * Standards CSV computed by the AI assistant while the form properties panel was closed.
     * Consumed and cleared by MultiSelect on its next instantiation (when the panel opens).
     */
    pendingStandards?: string;
    /**
     * Updates the {@link EPManager }'s available options.
     *
     * @param options The CSV containing the entire now available options. */
    updateEPManager: (options: string) => void;
    /**
     * Updates the {@link SVManager }'s available options.
     *
     * @param options The CSV containing the entire now available options. */
    updateSVManager: (options: string) => void;
    /**
     * Called whenever the API-Doc Manager's **Close**-{@link HTMLButtonElement } is clicked. */
    managerClosed: (event: Event) => void;
    /**
     * Called whenever the API-Doc Manager's **Maximize**-{@link HTMLButtonElement } is clicked.
     * Toggles the manager host container's fullscreen (`--maximized`) state. */
    managerMaximize: (event: Event) => void;
    /** Gets an API-Doc Manager translation resource.*/
    retrieveManagerTranslatedResource(id: string): string;
  };
}
